function magneticTarget(point){
  if(!state.connect)return null;const targetPort=state.connect.port==="out"?"in":"out",threshold=56/Math.max(.25,state.view.scale);let best=null;
  objects().filter(o=>o.id!==state.connect.from&&o.visible!==false).forEach(obj=>{const x=targetPort==="in"?obj.x:obj.x+obj.w,y=obj.y+obj.h/2,distance=Math.hypot(point.x-x,point.y-y);if(distance<=threshold&&(!best||distance<best.distance))best={id:obj.id,port:targetPort,x,y,distance}});return best
