function bcFileShortLabel(obj){const name=String(obj?.fileName||obj?.name||"FILE"),ext=(name.split(".").pop()||"").toUpperCase().slice(0,4),mime=String(obj?.mime||"");if(mime==="application/pdf")return"PDF";if(mime.startsWith("audio/"))return"♪";if(mime.startsWith("video/"))return"▶";if(/zip|rar|7z|tar|gzip/.test(mime)||/\.(zip|rar|7z|tar|gz)$/i.test(name))return"ZIP";if(/spreadsheet|excel|csv/.test(mime)||/\.(xls|xlsx|csv)$/i.test(name))return"XLS";if(/word|document|text/.test(mime)||/\.(doc|docx|txt|rtf|md)$/i.test(name))return ext||"TXT";return ext||"FILE"}
function bcFileIconMarkup(obj){const label=bcFileShortLabel(obj),kind=label==="PDF"?"pdf":label==="♪"?"audio":label==="▶"?"video":label==="ZIP"?"archive":label==="XLS"?"sheet":/^(TXT|DOC|DOCX|MD|RTF)$/.test(label)?"doc":"file";return `<div class="compact-file-icon file-kind-${kind}" title="${esc(obj.fileName||obj.name)}"><svg viewBox="0 0 64 72" aria-hidden="true"><path d="M11 3h29l13 13v53H11z"/><path d="M40 3v14h13"/></svg><b>${esc(label)}</b></div>`}
function connectionPortPoint(obj,port="e"){const x=Number(obj.x)||0,y=Number(obj.y)||0,w=Math.max(1,Number(obj.w)||1),h=Math.max(1,Number(obj.h)||1),map={nw:[0,0],n:[.5,0],ne:[1,0],e:[1,.5],se:[1,1],s:[.5,1],sw:[0,1],w:[0,.5]},p=map[port]||map.e;return{x:x+w*p[0],y:y+h*p[1]}}
